package com.andye.warmod.phalanx.network;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;import com.andye.warmod.block.entity.PhalanxBlockEntity;import com.andye.warmod.phalanx.PhalanxGunStatus;public final class PhalanxNetworking{private static boolean registered;private PhalanxNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxShotPayload.TYPE,ClientboundPhalanxShotPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxImpactPayload.TYPE,ClientboundPhalanxImpactPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxStatePayload.TYPE,ClientboundPhalanxStatePayload.STREAM_CODEC);registered=true;}public static void sendState(ServerLevel l,PhalanxBlockEntity turret){ClientboundPhalanxStatePayload p=new ClientboundPhalanxStatePayload(turret.turretId(),l.getGameTime(),turret.yaw(),turret.pitch(),turret.barrelSpin(),turret.bloom(),turret.rounds(),turret.status().ordinal(),turret.enabled(),turret.status()==PhalanxGunStatus.FIRING);for(var player:PlayerLookup.tracking(l,turret.getBlockPos()))ServerPlayNetworking.send(player,p);}public static void send(ServerLevel l,CustomPacketPayload p){for(var player:PlayerLookup.level(l))ServerPlayNetworking.send(player,p);}}
